470	pub enum CheckpointMode {
471	    /// Do as much as possible w/o blocking
472	    PASSIVE = ffi::SQLITE_CHECKPOINT_PASSIVE,
473	    /// Wait for writers, then checkpoint
474	    FULL = ffi::SQLITE_CHECKPOINT_FULL,
