522	/// The commit hook registered on a connection.
523	///
524	/// Both `commit_hook` and `try_commit_hook` share this single registration:
525	/// the most recent call to either entry point replaces the previous hook,
526	/// and unregistering either one removes whichever hook is current.
527	enum CommitHook {
528	    Simple(Box<dyn FnMut() -> bool + Send>),
529	    Fallible(Box<dyn FnMut() -> Result<bool> + Send>),
530	}
531	
532	struct CommitHookState {
533	    hook: CommitHook,
534	    /// The reason the fallible hook rejected the most recent commit attempt,
535	    /// to be reported by the call that observes SQLite's
536	    /// `SQLITE_CONSTRAINT_COMMITHOOK` error. Reset on every hook invocation,
537	    /// so a stale reason can never be attributed to a later failure.
538	    error: Option<Error>,
539	}
540	
541	unsafe extern "C" fn commit_hook_callback(p_arg: *mut c_void) -> c_int {
542	    unsafe {
543	        let state: *mut CommitHookState = p_arg.cast();
544	        match &mut (*state).hook {
545	            CommitHook::Simple(hook) => {
546	                let r = catch_unwind(AssertUnwindSafe(hook));
547	                c_int::from(r.unwrap_or_default())
548	            }
549	            CommitHook::Fallible(hook) => {
550	                let r = catch_unwind(AssertUnwindSafe(hook));
551	                let (rollback, error) = match r {
552	                    Ok(Ok(rollback)) => (rollback, None),
553	                    Ok(Err(err)) => (true, Some(err)),
554	                    Err(_) => (true, Some(Error::UnwindingPanic)),
555	                };
556	                (*state).error = error;
557	                c_int::from(rollback)
558	            }
559	        }
560	    }
561	}
562	
563	/// If `code` reports that the commit hook on `db` rejected a commit
564	/// (`SQLITE_CONSTRAINT_COMMITHOOK`) and the currently registered fallible
565	/// hook provided a reason, take and return it. The reason is consumed, so it
566	/// is reported at most once, by the first call that observes the rejection.
567	pub(crate) unsafe fn take_try_commit_hook_error(
568	    db: *mut ffi::sqlite3,
569	    code: c_int,
570	) -> Option<Error> {
571	    if db.is_null()
572	        || (code != ffi::SQLITE_CONSTRAINT_COMMITHOOK
573	            && ((code & 0xff) != ffi::SQLITE_CONSTRAINT
574	                || unsafe { ffi::sqlite3_extended_errcode(db) }
575	                    != ffi::SQLITE_CONSTRAINT_COMMITHOOK))
576	    {
577	        return None;
578	    }
579	    let state = unsafe { ffi::sqlite3_get_clientdata(db, c"sqlite3_commit_hook".as_ptr()) }
580	        .cast::<CommitHookState>();
581	    if state.is_null() {
582	        return None;
583	    }
584	    unsafe { (*state).error.take() }
585	}
