    pub fn try_authorizer<F>(&mut self, hook: Option<F>) -> Result<()>
    where
        F: for<'r> FnMut(AuthContext<'r>) -> Result<Authorization> + Send + 'static,
    {
        self.db.borrow_mut().try_authorizer(hook)
